import { useState } from "react";
import { Nav } from "./ui/Nav";
import { Button } from "./ui/Button";
import { SailIcon } from "./icons";

const links = [
  { href: "#courses", label: "Courses" },
  { href: "#instructors", label: "Instructors" },
  { href: "#contact", label: "Contact" },
];

export function SiteHeader() {
  const [open, setOpen] = useState(false);

  return (
    <Nav className="border-neutral-200 bg-white/90 dark:border-white/10 dark:bg-[#08192e]/90">
      <div className="mx-auto flex max-w-6xl items-center justify-between px-6 py-4">
        <a href="#top" className="flex items-center gap-2.5">
          <span className="flex h-9 w-9 items-center justify-center rounded-full bg-teal-600 text-white">
            <SailIcon className="h-5 w-5" />
          </span>
          <span className="text-lg font-semibold tracking-tight text-[#0b2545] dark:text-white">
            Harbourline
            <span className="ml-1 font-normal text-teal-600 dark:text-teal-400">Sailing School</span>
          </span>
        </a>

        <div className="hidden items-center gap-8 md:flex">
          {links.map((l) => (
            <a
              key={l.href}
              href={l.href}
              className="text-sm font-medium text-neutral-600 transition-colors hover:text-[#0b2545] focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-teal-600 dark:text-neutral-300 dark:hover:text-white"
            >
              {l.label}
            </a>
          ))}
          <Button
            variant="primary"
            className="bg-teal-600 hover:bg-teal-700 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-teal-600"
          >
            <a href="#contact">Book a taster sail</a>
          </Button>
        </div>

        <button
          type="button"
          onClick={() => setOpen((v) => !v)}
          aria-expanded={open}
          aria-label="Toggle navigation menu"
          className="flex h-10 w-10 items-center justify-center rounded-lg text-[#0b2545] focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-teal-600 md:hidden dark:text-white"
        >
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={1.8} className="h-6 w-6">
            {open ? (
              <path d="M6 6l12 12M18 6 6 18" strokeLinecap="round" />
            ) : (
              <path d="M4 7h16M4 12h16M4 17h16" strokeLinecap="round" />
            )}
          </svg>
        </button>
      </div>

      {open && (
        <div className="border-t border-neutral-200 bg-white px-6 py-4 md:hidden dark:border-white/10 dark:bg-[#08192e]">
          <div className="flex flex-col gap-4">
            {links.map((l) => (
              <a
                key={l.href}
                href={l.href}
                onClick={() => setOpen(false)}
                className="text-sm font-medium text-neutral-700 dark:text-neutral-200"
              >
                {l.label}
              </a>
            ))}
            <Button
              variant="primary"
              className="bg-teal-600 hover:bg-teal-700"
              onClick={() => setOpen(false)}
            >
              <a href="#contact">Book a taster sail</a>
            </Button>
          </div>
        </div>
      )}
    </Nav>
  );
}

