    name: "Mara Voss",
    role: "Head Instructor · RYA Yachtmaster Ocean",
    bio: "Twenty years teaching at Harbourline, with two transatlantic races and a circumnavigation behind her. Mara runs our Offshore Passage course personally.",
  },
  {
    icon: SailIcon,
    gradient: "from-teal-700 to-teal-500",
    name: "Theo Lindqvist",
    role: "Dinghy & Racing Coach",
