  },
  {
    icon: CompassIcon,
    gradient: "from-slate-700 to-slate-500",
    name: "Priya Anand",
    role: "Cruising & Navigation",
    bio: "A professional yacht delivery skipper who has crossed three oceans. Priya leads Coastal Cruising and our shore-based navigation evenings.",
  },
  {
    icon: AnchorIcon,
    gradient: "from-amber-700 to-amber-500",
    name: "Sam Okafor",
    role: "Junior Program Lead",
    bio: "A marine biologist and RYA youth sailing coach who has run our Junior Sailors summer program for eight seasons.",
  },
];

export function Instructors() {
  return (
    <section id="instructors" className="bg-[#f4f8fb] py-20 dark:bg-[#08192e]">
      <div className="mx-auto max-w-6xl px-6">
        <div className="max-w-2xl">
          <p className="text-sm font-semibold uppercase tracking-wide text-teal-600 dark:text-teal-400">
            Instructors
          </p>
          <h2 className="mt-2 text-3xl font-bold tracking-tight text-[#0b2545] sm:text-4xl dark:text-white">
            Taught by people who sail for a living
          </h2>
          <p className="mt-4 text-lg text-neutral-600 dark:text-slate-300">
            Every instructor at Harbourline holds current RYA qualifications and spends part of
            each year racing, cruising or delivering yachts — not just teaching from a manual.
          </p>
        </div>

        <div className="mt-12 grid gap-6 sm:grid-cols-2 lg:grid-cols-4">
          {instructors.map((person) => (
            <Card
              key={person.name}
              className="border-neutral-200 bg-white text-center dark:border-white/10 dark:bg-[#0f2340]"
            >
              <div
                className={`mx-auto flex h-20 w-20 items-center justify-center rounded-full bg-gradient-to-br ${person.gradient} text-white shadow-sm`}
              >
                <person.icon className="h-9 w-9" />
              </div>
              <h3 className="mt-4 text-lg font-semibold text-[#0b2545] dark:text-white">
                {person.name}
              </h3>
              <p className="mt-1 text-sm font-medium text-teal-600 dark:text-teal-400">
                {person.role}
              </p>
              <p className="mt-3 text-sm leading-relaxed text-neutral-600 dark:text-slate-300">
                {person.bio}
              </p>
            </Card>
          ))}
        </div>
      </div>
    </section>
  );
}

